// A color space as GSHSCENE_Color_Space spells it.  GCOL numbering: primaries UNKNOWN 0, SRGB 1, ADOBE_RGB 2,
// DISPLAY_P3 3, BT2020 4; transfer UNKNOWN 0, LINEAR 1, SRGB 2, GAMMA 3.  The zero Space {0, 0, 0.0} is the target's
// space; in these vectors the target's space is the case's `layer` (a zero `layer` appears only where every
// space of the case is zero).
struct Space {
  unsigned primaries, transfer;
  double gamma;
};

// An image as image.h describes it.  layout is the number of samples a pixel has: 1 gray, 3 RGB, 4 RGBA.  type 0
// unorm, 1 float.  bits 8, 12, 16 or 32.  alpha_form 0 none, 1 straight, 2 premultiplied.  samples: width * height *
// layout values, row-major, channels in storage order; a float is its IEEE binary32 bit pattern.
struct Image {
  const char * name;
  unsigned width, height, layout, type, bits, alpha_form, alpha_only;
  Space space;
  const std::uint32_t * samples;
};

// A point sample (NEAREST 0, LINEAR 1, CUBIC 2) at image-space point (u, v), y down, texel (i, j) covering
// [i, i + 1) x [j, j + 1).  window: x0, y0, x1, y1 in texels, all zero for the whole image.  extend: PAD 0, REPEAT 1,
// REFLECT 2, NONE 3.  filter_space: zero for the image's own space.  expected: the premultiplied value in `layer`
// without the paint's alpha multiplier; for an alpha-only image expected[3] is the filtered alpha and
// expected[0..2] are 0.  A sink matches within tolerance * max(1, max over k of |expected[k]|).  Where not exact, tolerance is max(1e-12, 2^-47 C / max(1, max |expected|)), C = sum |w_i| M_i over the taps (w_i the weight, 1 for NEAREST, M_i the largest absolute component the tap passes through: premultiplied in its own space, straight, converted, premultiplied in F; plus the layer step's own largest magnitude): a weighted sum of n terms errs by at most n 2^-53 C in any order, which huge cancelling taps (saturated floats, gamut conversion) make large.  in_band: a NEAREST point within
// 2^-16 texel of a texel boundary (edge-mode seams included): a sink may take either neighbour.
struct Point {
  const char * name;
  int image;
  int window[4];
  unsigned extend_x, extend_y;
  unsigned filter;
  Space filter_space;
  Space layer;
  double u, v;
  double expected[4];
  double tolerance;
  int in_band;
};

// An AREA sample: the exact mean of the extended image over the parallelogram origin + s edge_a + t edge_b,
// s and t in [0, 1] (image space).  The other fields as Point.
struct Area {
  const char * name;
  int image;
  int window[4];
  unsigned extend_x, extend_y;
  Space filter_space;
  Space layer;
  double origin[2], edge_a[2], edge_b[2];
  double expected[4];
  double tolerance;
};

// IP8: m = {m00, m01, m10, m11}, the linear part of the composed map.  expected is 1 when every direction is
// stretched (the smallest singular value exceeds 1), decided exactly on the doubles.
struct Stretch {
  const char * name;
  double m[4];
  int expected;
};

